const go=h=>{
 const t=$(h);if(!t)return;
 const wasMenuOpen=mo;
 const jump=()=>{
  shut();
  setActiveNav(h.slice(1));
  if(L){L.resize();L.scrollTo(t,{immediate:wasMenuOpen,duration:wasMenuOpen?0:1.05,onComplete:rfs})}
  else t.scrollIntoView({behavior:wasMenuOpen?'auto':'smooth'});
  rfs();
 };
 const wipeEl=$('#wipe');
 if(!G||!wasMenuOpen||!wipeEl)return jump();
 gsap.killTweensOf(wipeEl);
 gsap.timeline()
  .fromTo(wipeEl,{yPercent:0},{yPercent:-100,duration:.45,ease:'power4.inOut'})
  .add(jump)
  .to(wipeEl,{yPercent:-200,duration:.55,ease:'power4.inOut'})
  .set(wipeEl,{yPercent:0});
};
