/* ---- skills: drag inertia ---- */
const act=new Set();
const cs=$$('.sk,.sk .chip').map(el=>({el,k:el.classList.contains('sk')?.45:1.8,x:0,y:0,vx:0,vy:0,d:false,p:false}));
const put=c=>{c.el.style.translate=`${c.x}px ${c.y}px`;c.el.style.rotate=`${clamp(-22,22,c.vx*c.k)}deg`};
addTick(()=>act.forEach(c=>{
 if(c.d)return;
 c.vx+=-c.x*.05;c.vy+=-c.y*.05;
 c.vx*=.91;c.vy*=.91;
 c.x+=c.vx;c.y+=c.vy;
 put(c);
 if(Math.abs(c.x)+Math.abs(c.y)+Math.abs(c.vx)+Math.abs(c.vy)<.08){
  c.x=c.y=c.vx=c.vy=0;
  c.el.style.translate=c.el.style.rotate='';
  c.el.classList.remove('moving');
  act.delete(c);
 }
}));
cs.forEach(c=>{
 let sx=0,sy=0,ox=0,oy=0,pid=null;
 c.el.addEventListener('pointerdown',e=>{
  if(e.pointerType==='touch'||e.button!==0)return;
  e.stopPropagation();
  c.p=true;c.d=false;
  sx=e.clientX;sy=e.clientY;ox=c.x;oy=c.y;pid=e.pointerId;
 });
 c.el.addEventListener('pointermove',e=>{
  if(!c.p)return;
  const dx=e.clientX-sx,dy=e.clientY-sy;
  if(!c.d){
   if(Math.hypot(dx,dy)<4)return;
   c.d=true;act.add(c);c.vx=c.vy=0;
   c.el.classList.add('dr','moving');
   try{c.el.setPointerCapture(pid)}catch(_){}
  }
  const nx=ox+dx,ny=oy+dy;
  c.vx=.6*c.vx+.4*(nx-c.x);
  c.vy=.6*c.vy+.4*(ny-c.y);
  c.x=nx;c.y=ny;
  put(c);
 });
 const up=()=>{
  if(!c.p)return;
  c.p=false;
  if(c.d){c.d=false;c.el.classList.remove('dr')}
 };
 c.el.addEventListener('pointerup',up);
 c.el.addEventListener('pointercancel',up);
 c.el.addEventListener('lostpointercapture',up);
});

/* ---- always-on interactive constellation particle network + cursor trail ---- */
const cv=$('#trail'),ctx=cv.getContext('2d');
let pts=[],tCurX=innerWidth/2,tCurY=innerHeight/2,lastSY=scrollY,sVel=0;
const rs=()=>{cv.width=innerWidth;cv.height=innerHeight};rs();addEventListener('resize',rs);
addEventListener('scroll',()=>{sVel=clamp(-24,24,scrollY-lastSY);lastSY=scrollY},{passive:true});
const MOTES=innerWidth<768?18:Math.min(38,Math.max(22,Math.floor(innerWidth/40)));
const motes=Array.from({length:MOTES},(_,i)=>({
 x:Math.random()*innerWidth,
 y:Math.random()*innerHeight,
 vx:(Math.random()-.5)*.48,
 vy:(Math.random()-.5)*.48,
 r:1.1+Math.random()*1.6,
 a:.18+Math.random()*.28,
 c:i%3===0?'240,166,192':'139,140,248'
}));
addTick(()=>{
 ctx.clearRect(0,0,cv.width,cv.height);
 sVel*=.9;
 for(let i=0;i<motes.length;i++){
  const m=motes[i];
  m.x+=m.vx;
  m.y+=m.vy-sVel*.1;
  if(m.x<0)m.x=cv.width;else if(m.x>cv.width)m.x=0;
  if(m.y<0)m.y=cv.height;else if(m.y>cv.height)m.y=0;
  ctx.fillStyle=`rgba(${m.c},${m.a})`;
  ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,Math.PI*2);ctx.fill();
  for(let j=i+1;j<motes.length;j++){
   const n=motes[j],dx=m.x-n.x,dy=m.y-n.y,d2=dx*dx+dy*dy;
   if(d2<16000){
    ctx.strokeStyle=`rgba(139,140,248,${(1-d2/16000)*.11})`;
    ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(m.x,m.y);ctx.lineTo(n.x,n.y);ctx.stroke();
   }
  }
  const cdx=m.x-tCurX,cdy=m.y-tCurY,cd2=cdx*cdx+cdy*cdy;
  if(cd2<24000){
   ctx.strokeStyle=`rgba(139,140,248,${(1-cd2/24000)*.22})`;
   ctx.lineWidth=1;
   ctx.beginPath();ctx.moveTo(m.x,m.y);ctx.lineTo(tCurX,tCurY);ctx.stroke();
  }
 }
 pts=pts.filter(p=>(p.l-=.045)>0);
 pts.forEach(p=>{ctx.fillStyle=`rgba(139,140,248,${p.l*.32})`;ctx.beginPath();ctx.arc(p.x,p.y,p.l*12,0,7);ctx.fill()});
});

